import os
import signal
import time

from flask import Flask, Response, request
from prometheus_client import CONTENT_TYPE_LATEST, Counter, Histogram, generate_latest

app = Flask(__name__)

REQUESTS = Counter(
    "mock_app_http_requests_total",
    "HTTP requests handled by the mock application.",
    ["method", "path", "status"],
)
ERRORS = Counter(
    "mock_app_errors_total",
    "Errors deliberately generated by the mock application.",
    ["type"],
)
LATENCY = Histogram(
    "mock_app_request_duration_seconds",
    "Mock application request latency.",
    ["path"],
)


@app.after_request
def record_request(response: Response) -> Response:
    if request.path != "/metrics":
        REQUESTS.labels(request.method, request.path, response.status_code).inc()
    return response


@app.get("/")
@LATENCY.labels("/").time()
def index() -> dict[str, str]:
    return {
        "service": "mock-observable-app",
        "status": "ok",
        "metrics": "/metrics",
        "error_test": "/simulate-error",
        "cpu_test": "/simulate-cpu?seconds=30",
    }


@app.get("/healthz")
def health() -> dict[str, str]:
    return {"status": "healthy"}


@app.get("/readyz")
def ready() -> dict[str, str]:
    return {"status": "ready"}


@app.get("/metrics")
def metrics() -> Response:
    return Response(generate_latest(), mimetype=CONTENT_TYPE_LATEST)


@app.get("/simulate-error")
def simulate_error() -> tuple[dict[str, str], int]:
    ERRORS.labels("simulated").inc()
    return {"error": "simulated failure"}, 500


@app.get("/simulate-cpu")
def simulate_cpu() -> dict[str, float]:
    seconds = min(max(float(request.args.get("seconds", "10")), 0.1), 600.0)
    deadline = time.monotonic() + seconds
    value = 1.0
    while time.monotonic() < deadline:
        value = (value * 1.0000001) % 97.0
    return {"busy_seconds": seconds, "result": value}


@app.get("/simulate-crash")
def simulate_crash() -> Response:
    if os.getenv("ALLOW_CRASH_ENDPOINT", "false").lower() != "true":
        return Response("Crash endpoint disabled\n", status=403)
    ERRORS.labels("crash").inc()
    # Gunicorn is PID 1 in the container. Stopping it makes Kubernetes restart
    # the container instead of merely replacing one worker.
    os.kill(1, signal.SIGTERM)
    os._exit(1)
    return Response("Container terminating\n", status=503)  # pragma: no cover


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8080)
